p=Path('users.js');s=p.read_text(encoding='utf-8-sig').replace('label="全域（系統管理者）"','label="所有專案"').replace("project==='__global'?r.system:r.project===project","project==='__global'?r.system:!r.system&&r.project===project").replace("return (this.roles.find(r=>r.id===id)||{}).name||'未指派'","const role=this.roles.find(r=>r.id===id);return role?(role.system?'系統管理員':role.name):'未指派'").replace(":label=\"r.name+(r.enabled?'':'（停用）')\"",":label=\"(r.system?'系統管理員':r.name)+(r.enabled?'':'（停用）')\"").replace("projectNames(u){return [...new Set","projectNames(u){if(u.assignments.some(a=>a.project==='__global'))return '所有專案';return [...new Set");p.write_text(s,encoding='utf-8')
